<script setup>
/**
 * KeywordExtractor — key terms for a note as a tag cloud, generated by Gemini
 * (aiService). Technical terms are highlighted. No rule-based fallback.
 */
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { extractKeywords } from '../../services/aiService.js'

const { t } = useI18n()
const props = defineProps({
  content: { type: String, default: '' },
  limit: { type: Number, default: 12 }
})

const keywords = ref([])
const loading = ref(false)
const failed = ref(false)

async function run() {
  failed.value = false
  if (!props.content) { keywords.value = []; return }
  loading.value = true
  try {
    keywords.value = await extractKeywords(props.content, { limit: props.limit })
  } catch {
    failed.value = true
    keywords.value = []
  } finally {
    loading.value = false
  }
}

watch(() => props.content, run, { immediate: true })
</script>

<template>
  <div class="panel">
    <div class="section-title"><i class="bi bi-tags"></i>{{ t('keywords.title') }}</div>

    <p v-if="loading" class="kw-empty"><i class="bi bi-arrow-repeat spin"></i> {{ t('ai.generating') }}</p>
    <p v-else-if="failed" class="kw-empty">{{ t('ai.failed') }}</p>
    <p v-else-if="!keywords.length" class="kw-empty">{{ t('keywords.empty') }}</p>

    <template v-else>
      <div class="keyword-cloud">
        <span
          v-for="k in keywords"
          :key="k.word"
          class="keyword-tag"
          :class="{ 'is-technical': k.technical }"
          :title="k.technical ? 'Technical term' : 'Frequent term'"
        >
          {{ k.word }}<span class="kw-count">{{ k.count }}</span>
        </span>
      </div>

      <p class="kw-legend">
        <span class="keyword-tag is-technical kw-legend-chip">term</span>
        {{ t('keywords.legend') }}
      </p>
    </template>
  </div>
</template>
